def inspect_lag(mapping):
    if 'lag' not in mapping:
        return {'accepted': False, 'lag': None}
    lag = mapping['lag']
    if lag is None:
        return {'accepted': False, 'lag': None}
    if type(lag) is not int or type(lag) is bool or not (-1 <= lag <= 8):
        return {'accepted': False, 'lag': None}
    return {'accepted': True, 'lag': lag}
